import{_ as a,c as e,o as t,ah as i}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易经传集解卷八","description":"周易经传集解 - 周易经传集解卷八","frontmatter":{"title":"周易经传集解卷八","description":"周易经传集解 - 周易经传集解卷八"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/009.md","filePath":"zh/classics/jingchuan-jijie/009.md"}'),s={name:"zh/classics/jingchuan-jijie/009.md"};function n(c,p,r,_,o,l){return t(),e("div",null,[...p[0]||(p[0]=[i('<p>钦定四库全书</p><h1 id="周易经传集解卷八" tabindex="-1">周易经传集解卷八 <a class="header-anchor" href="#周易经传集解卷八" aria-label="Permalink to “周易经传集解卷八”">​</a></h1><p>宋林栗撰</p><p>序卦曰：「有大者不可以盈，故受之以</p><p>谦。」谦犹歉也，歉然不自满之貌也。书曰「满招损，谦受益」，子曰「天道亏盈而益谦」，皆以盈满对谦而称也。「谦」之成卦，「大有」之变也。自「大有」之「谦」，变其四阳，其不动者六五、九三耳。以六五而有九三，可谓有大矣。又益之以四阳，则其所有者，不亦盛大而富有乎？六五为君，九三为臣，变其四阳，而君臣歉然自居于寡弱之中，是以谓之「谦」也。楚武王伐随，入告夫人邓曼曰：「余心荡。」邓曼叹曰：「王禄尽矣。」盈而荡，天之道也。昔之有大物者，聪明圣智，守之以愚；富贵崇高，守之以卑。夫是故满而不溢，高而不危，此「谦」之所以次大有也。是故「小畜」，臣也，以一柔而畜五刚，既畜矣，不可以不履，圣人取之。乾兑而谓之「履」焉。泽宜在天下者也，上天下泽，「履」之象也。「大有」，君也，以一柔而有五刚，既有矣，不可以不「谦」。圣人取诸「坤」、「艮」而谓之「谦」焉。山宜在地上者也，山在地中，「谦」之象也。此「履」、「谦」之辨也。</p><p>谦：亨，君子有终。彖曰：「谦，亨」。天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可逾，君子之终也。</p><p>下艮上坤。成卦曰「谦」者，初为艮，二为坎，三为震，四为坤。坤为母，震为长男，坎为中男，艮为少男。言坤则包三女，言三子则包乾。坤者，阴之尊；艮者，阳之少。阳居其少而阴处其尊，柔行于上而刚际于下，是以谓之谦也。故子曰：「天道下济而光明，地道卑而上行。」程氏曰：「济」当作际，字之讹也。夫乾劳于次，成于艮，而出乎震。坎为幽，震为明，是谓下际而光明，九三是也。夫坤𬯎然居于至顺，而三阳之类莫之能逾，是谓卑而上行，六四是也。其在六位，初二为地，三四为人，五上为天。初谦而二盈，三谦而四盈，五谦而上盈。三谦之位，其数皆奇；三盈之位，其数皆偶。奇为阳，偶为阴。阳为富，阴为贫。消息盈虚之理，于此可见矣。故子曰：「天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。」观诸日月，则见亏益之理；考诸山川，则见变流之形；验诸灾祥，则知害福之意；稽诸毁誉，则知好恶之情。或曰：三才之道，六位著矣。鬼神之象，于何而取之？曰：三才备，则鬼神之道行乎其中矣。岂于三才之外，而别求鬼神之象哉？「谦，亨，君子有终」，何谓也？子曰：谦尊而光，卑而不可逾，君子之终也。天道下际而光明，是谓尊而光；地道卑而上行，是谓不可逾。天不下际，则大明不升；地不上行，则云雨不施。大明升乎天上，云雨流乎地下，「谦」之所以「亨」也。「尊而光，卑而不可逾」，岂不信哉？是故君子居尊而行谦，则其道益光；处卑而行谦，则物莫能逾：此其所以克终也。在卦五阴而一阳，阳居下卦之上，上卦之下，是故兼乎尊卑，有终之义也。诗云：「靡不有初，鲜克有终。」以九三之盛德，有九三之大功，居九三之极位，而不以谦行之终者，鲜矣。是以他卦九三，类多㓙咎，至于大有之三，犹有「小人弗克」之象，惟「谦」则曰「君子有终」。象既发之于前，爻又申之于后，以明有终之义在于九三，而不在上六也。易于他卦爻象，可以互见，则微出其意，使学者深求而得之。至于谦之有终，苟不辞费，则学者必以上六当之矣。是以两系其辞，而指言其处。圣人之于后学，眷眷如此，可以不尽心乎哉！</p><p>象曰：地中有山，「谦」，君子以裒多益寡，称物平施。</p><p>地者，坤也；山者，艮也。山在地上，有损而无益；其在地中，有益而无损。君子观此之象，裒多以益寡，先人而后己。自处其身于卑贱之地，然后天下之人从而尊之贵之。是故山宜在上，今在地中，裒而益之，山愈高矣。老子曰：「圣人欲上人，以其言下之；欲先人，以其身后之。」杨子曰：「自后者，人先之；自下者，人高之。」此则谦之义也。或曰：山虽在地中，地固有在其下者矣。若裒多以益寡，是将凿山为地以取平，山又乌能愈高哉？曰：夫物之不齐，物之情也，岂得比而同之哉？比而同之，则是无父子君臣，无尊卑贵贱也，而可乎？圣人之所谓「裒多益寡」者，称物而平其施也。山宜高也，寡则益之；地宜平也，多则裒之。各称其物，乃为平施也。</p><p>杂卦曰：「谦轻而豫怠也。」</p><p>轻与重对，怠与勤对。谦为轻，则豫为重；豫为怠，则谦为勤。国之兴也，日以为不足；其亡也，若有余。所谓轻者，不足之谓也；所谓重者，有余之谓也。譬之舟车，轻则行，重则覆；譬之权衡，轻则举，重则废。故曰：「谦者，德之柄也。」非以其轻故欤？老子所处上而人不重，居前而人不害，亦谦轻之义也。是以「谦」之诸爻，惟上六居物之上。上六所承，虽曰「鸣谦」，非其志也。自五以降，皆以所承为象，而著其谦轻之美焉。初六「谦谦」，则可以涉难。六二「鸣谦」，则可以守正。九三「劳谦」，则可以有终。六四「㧑谦」，则可以不违。六五「不富」，则可以侵伐而无不利矣。「谦」之为轻，不其然乎？</p><p>初六：谦谦君子，用涉大川，吉。象曰：「谦谦君子」，卑以自牧也。初六，「艮」也，以阴居刚，而在下卦之下，承于六二之「坎」，故曰「谦谦」。「谦」之言下也，下卦之下，「谦」而又「谦」者也。夫所为「谦」者，谓其高而惧其危，谓其满而畏其溢，谓其有余而损之以补不足也。今也居于最下，名为极卑，而又以「谦」行之，宜若过乎恭者矣，故曰「用涉大川」。二体「坎」，「坎」为险，有「大川」之象焉。「谦」而又「谦」，损而又「损」，涉难可矣，非常行之道也。「谦损」之极，无异允庸，以此涉难，其谁害之？故曰「吉」。子曰：「谦谦君子，卑以自牧也。」夫「谦」者，生于盈也，所以保其名而存其位也。无名之可保，无位之可存，而「谦谦」不已者，凡以自牧其身而已矣。牧之为言，其养之以候用乎？</p><p>六二：鸣谦，贞吉。象曰：「鸣谦贞吉」，中心得也。</p><p>六二，「坎」也。以阴居柔而在下卦之中，承于九三之「震」，故曰「鸣谦」。震为善鸣，故有鸣象。苏氏曰：雄鸣则雌应，故易阳唱而阴和，寄之于鸣。三以鸣唱于二，二谦不敢和，是之谓「鸣谦」，谦于鸣者也。夫三以一阳而为五阴之主，上下无阳以为之敌，二近而承焉，有求而弗应，有倡而弗和，宜若咎矣。然二居中履正，以三之非其配也，礼恭而辞顺，斯可以保其正矣，故曰「贞吉」。子曰：「鸣谦贞吉，中心得也。」以其中正，知其得于诚心，而非伪为之也。</p><p>九三，劳谦，君子有终，吉。象曰：「劳谦君子」，万民服也。</p><p>九三上体为「震」，下体亦为「震」，以阳居刚而在下卦之上，承于六四之「坎」，故曰「劳谦」。「震」为动，「坎」为劳。「劳」者，功也。古之行赏，事功曰「劳」，因其劳而劳之也。方谦之时，六五在上，三以一阳动于五阴之中，上承下接，可谓劳矣。六四以大君之命，因其劳而劳之，三谦而不敢受，是之谓「劳谦」，谦于劳者也。诗云：「旡言不酬，旡德不报。」三之有劳而享其报，人之常情也。而乃逡巡退避，自处于无功之地，何哉？书不云乎：有其善，丧厥善；矜其能，丧厥功。汝惟不矜，天下莫与汝争能；汝惟不伐，天下莫与汝争功。劳而能「谦」，所以保其终也。故曰「君子有终」。又曰「吉」。子曰：「劳谦君子，万民服也。」六四体「坤」，「坤」为众，为民。上下五阴，其数十，故有万民之象焉。以震下「坎」，其象为屯；以震下「坤」，是为初九。夫子赞之曰：「以贵下贱，大得民也。」然则「劳谦君子，得万民之服」，其亦「以贵下贱」之义欤？何则？以德而上人者，人之所忌也；以才而傲人者，人之所弃也；以功而骄人者，人之所疾也；以位而陵人者，人之所恶也。今也德盛而才高，功崇而位显，然而天下帖然无异辞者，岂非劳而能谦，有以服其心也哉？故子曰：「劳而不伐，有功而不德，厚之至也。」语以其功下人者也。德言盛，礼言恭。谦也者，致恭以存其位也。尽斯道者，周公其人矣。</p><p>六四：无不利，㧑谦。象曰：「无不利，㧑谦」，不违则也。</p><p>六四上体为「坤」，下体为「坎」，以阴居柔而在上卦之下，承于六五之「艮」，故曰：「无不利，㧑谦。」「艮」为手，故有「㧑」象。「㧑」，指㧑也。上之使下谓之「㧑」。六四居近君之位，五之所㧑也。九三居六四之下，四之所㧑也。五之㧑四也，将使之；四之㧑三也，四谦而不敢专，是之谓「㧑谦」，谦于「㧑」者也。夫以六居四，履当其位，上承六五，下接九三，以君命命之，宜无不顺矣。然且畏远权任，凡所指㧑，必出于上，何哉？盖以赏罚号令，人主之柄，为臣之道，无敢专行，虽君有命，弗敢承也。夫然，故居于上体之下，以「坤」承「艮」而五不疑；处于下卦之上，以「坎」乘「震」而三不忌。既谦且顺，何不利之有哉？故子曰：「无不利，㧑谦，不违则也。」「则」之言法也，事君之常道，万世之通法也。</p><p>六五：不富以其邻，利用侵伐，无不利。象曰：「利用侵伐」，征不服也。</p><p>六五，「艮」也，以阴居刚而在上卦之中，介于六四、上六之间，二爻皆「坤」，而四又「坎」也，故曰「不富以其邻」。阳为富，阴为贫。五以柔居尊，而承乘皆阴，故有「不富」之象，与「泰」之六五同也。「邻」谓四也，以其在五左右，故以「邻」言之。「以」，用也。传曰：能左右之曰以，四之称㧑是也。不富而能以其邻者，其志同也，故曰：「利用侵伐，无不利。」能以其邻，则迩臣顺矣。迩臣顺，则方伯连率莫不用命矣。方伯连率莫不用命，则四方之国苟有不服，可以侵伐而无不利矣。或曰：卦以谦为义，而六五之君乃不言「谦」，又有「侵伐」之象，何也？曰：「谦」之言下也，自初至五，皆以卑下为义。初在下卦之下，二在下卦之中，三在下卦之上，四在上卦之下，是以谓之「谦」也。若夫六五居尊，虽屈下于上六，然非「谦」之所宜施也。上居一卦之上，非所乘而乘焉，其不服之国乎？此五之所以致其侵伐者也。夫「谦」之六五，本于「大有」，谓其盛大而富有，是以变而为「谦」。其在「大有」，固已易而无备，今又以「谦」居之，外见其弱，内示其虚，戎将生心，民慢其政，「利用侵伐」，不亦宜乎？夫兵，㓙器也；战，危事也。圣人未尝不慎重言之，而六五之辞易者然，何也？孟子曰：「恭者不侮人，俭者不夺人。」「谦」之六五，其肯喜功好大，以干戈求益者哉？六以阴柔之资，居一卦之上，而乘大君之辱，天地神人之所不赦也。奉行天罚，何不利之有哉？子曰：利用侵伐，征不服也。司马法曰：「贼贤害民则伐之，负固不服则侵之。」舜征有苗，益赞于禹曰：「满招损，谦受益，时乃天道。」知舜、禹之师，然后知「谦」之六五有侵伐之义矣。</p><p>上六：鸣谦，利用行师，征邑国。象曰：「鸣谦」，志未得也。可「用行师」，征邑国也。</p><p>上六，「坤」也，以阴居柔，而在一卦之上，上无所承，而配于九三之「震」，故曰「鸣谦」。三以其鸣倡于上，上六谦而不应，是之谓「鸣谦」，「谦」于鸣者也。夫六二、上六，其为「鸣谦」一也。二「谦」而系之「贞吉」者，以三之非其配也。至于上六，其配在三，谦而不和，岂其情也哉？处势之高，乘于六五，欲自为倡而未获其志，是以难于从三，而托谦以为辞也。三以一阳为五阴之主，令不行于其配，岂其任之而不治乎？故曰「利用行师，征邑国」。为九三言之也。三为「震」，「震」为动，自四以往，为「坎」、为「坤」。「坎」为险，「坤」为众，为「邑」，故有「行师」「征邑国」之象。以「坎」制「坤」，其象为「师」；以「震」行「坎」，是为九二，所谓行险而顺者也。上三之配，谦而不应，其邑人不服之象乎？自五而言之，则为强梗；自三而言之，则为邑国。三，臣道也，应不在五，非其邑国，不得击征矣。故子曰：「鸣谦，志未得也，可用行师，征邑国也。」在上为邑，在四为师，惟变所适，不其然乎？序卦曰：「有大而能谦必豫，故受之以</p><p>豫。」</p><p>「豫」之言暇也，国家闲暇，人民和乐之谓也。「豫」之成卦，「谦」之反也。「艮」之一阳在三阴之下，歉然有不足之意，所以为「谦」也。艮反成「震」，而出乎「坤」，九三进而居四，动而上下应之，所以为「豫」也。诗云：「始于忧勤，终于逸乐。」有天下之大，而不以谦居之，则骄侈之心生，而忧勤之事废矣。欲国家之闲暇，人民之和乐，不可得也。古之圣人，视天下之治犹若未治，视国家之安犹若未安，是以自朝至于日中昃，不遑暇食，用咸和万民，此「谦」之所以致「豫」也。「豫」之训诂，不一而足，曰「暇豫」，曰「怠豫」，曰「备豫」，曰「疑豫」，皆「豫」之时义也。若夫「和豫」、「悦豫」，不出于「暇豫」之义矣。方国家闲暇之时，既有「和豫」之美，必有「怠豫」之渐；既有「备豫」之思，必有「疑豫」之失。是以圣人为卦，名之曰「豫」，取夫「暇豫」而戒夫「怠豫」者也，取夫「备豫」而戒夫「疑豫」者也。非故为是纷纷，本其时义而言之也。经曰「有大而能谦必豫」，谓「暇豫」也；「冥豫成有渝，旡咎」，谓「怠豫」也；「重门击柝，盖取诸豫」，谓「备豫」也；「旴豫悔，迟有悔」，谓「疑豫」也。而可以一义一之耶？今言易者，顾乃采摭经传之遗言，取其一偏而为之说，则「豫」之时义不全，而顺动之义不可得而见矣。豫：利建侯行师。彖曰：「豫，刚应而志行，顺以动，豫。」豫顺以动，故天地如之，而况「建侯行师」乎？天地以顺动，故日月不过而四时不忒；圣人以顺动，则刑罚清而民服。「豫」之时义大矣哉！</p><p>下坤上震成卦曰「豫」者，初为「坤」，二为「艮」，三为「坎」，四为「震」。「震」为动，「坎」为「陷」，「艮」为止，「坤」为顺。顺则动，则无往而不顺矣。何怠豫之渐而疑豫之失哉？以有陷止之象存乎其间也。怠则陷，疑则止，此卦之所以为「豫」也。「豫，利建侯行师」，何谓也？子曰：「豫」，刚应而志行，顺以动，豫。豫顺以动，故天地如之，而况建侯行师乎？所以为「豫」也，九四也。四以刚而体乎「震」，有应于下，而其志上行，顺以动，动而无不顺。以此建侯，则民从其令；以此行师，则众服其威，斯为利矣。震惊百里，「侯」之象也；以众行险，师之象也。在卦之屯，「震」在「坎」下，有「坤」象焉，其彖曰：「利建侯。」在「师」之二，「震」在「坎」中，有「坤」象焉，其繇曰：「在师中吉。」今「豫」之九四，「震」在「坤」上，而兼乎二卦之象，故「利建侯行师」也。所以然者，「坤」为至静而「震」出焉，是能柔能刚，能定能应之义也。昧者以为方豫之时，安有建侯行师之事？不知天地之道，所以行日月而成四时者，亦不过顺动而已。况夫有天下者，建侯行师，而可以不顺动乎哉？故曰：天地以顺动，故日月不过而四时不忒；圣人以顺动，则刑罚清而民服。「豫」之时义大矣哉！夫天地之行，昼夜而一周；月之行，三旬而一周；日之行，一岁而一周。然其朝出于东，而夕入于西，夕出于东，而朝没于西。昼夜以此而分，寒暑以此而平，四时以此而成。人见其然也，以为日月之时，而不知天地之顺动也。日月之行于天，如蚁之行于磨，蚁行迟而磨行速。天地以顺动，则日月不差其度矣。日月不差其度，则四时不失其序矣。圣人之为天下，建邦设都，树之君公，承以大夫师长，庶政惟和，万国咸宁，兵寝刑措，至于不用。人见其然也，以为公侯卿大夫之行，而不知圣人之顺动也。国家闲暇，及是时也，明其政刑，张其纲纪，礼乐征伐自天子出，顺者爵之，逆者诛之，建侯行师，以政天下，则刑罚清而民服，不亦宜乎？</p><p>象曰：雷出地奋，「豫」，先王以作乐崇德，殷荐之上帝，以配祖考。</p><p>地者，「坤」也。「奋」者，「震」也。夫万物资始于天，资生于地，方其战乎「乾」，劳乎「坎」，而归根复命于「艮」也。天地之德，不可得而见也。及乎雷出于地而奋乎天，其声震乎宇宙之间，草木昆虫，于以条达遂茂，然后天地生成之德，可得而言矣。先王观此之象，作为一代之乐，尊崇功德之所由致，经其盛大，荐之上帝，而以祖考配焉，报本反始之义也。故周公郊祀后稷以配天，宗祀文王于明堂以配上帝，美盛德之形容，以其成功告于神明者也。杂卦曰：「豫，怠也。」</p><p>常人之情，安则逸，逸则怠，怠则不急于事矣。圣人见其几而预为之计焉。夫几藏于兆朕之先，而事变于须臾之顷，明者察之，众人疑焉，皆豫怠之所生也。阳为刚，阴为柔；刚为动，柔为静。是以「豫」之诸爻，以阳居柔者，动于静者也；以阴居刚者，静于动者也；以阴居柔者，静而能静者也。方「豫」之时，可谓静矣。静而能动者，得动静之宜矣；静而能静者，其动不旋踵矣。若夫宜动而静，则其志怠矣，其可以久于「豫」哉？是故九四以阳居柔，体「震」而应「坤」，斯谓之顺动矣，以其在「豫」，尚有「勿疑」之戒焉。六二、上六以阴居柔，体「艮」而近于「震」，「震」反则为，「艮」反则为「震」，故二「介于石」而有「不终日」之吉，上虽「冥豫」而有「渝无咎」之象焉。乃若初六、六三、六五皆以柔居刚，体乎「坤」「坎」。「坤」者顺也；「坎」者陷也。顺者不能以自强，陷者不能以自振。是故初有志穷之㓙，三有不当之悔，五有乘刚之疾。「豫」之为怠，不其然乎！</p><p>初六：鸣豫，凶。象曰：「初六鸣豫」，志穷凶也。</p><p>初六，「坤」也。以阴居刚，而在下卦之下，配于九四之「震」，故曰「鸣豫」。「震」为善鸣，故有鸣象。九四以其鸣倡于初六，初六体乎「坤」而近承于「艮」，「豫」怠而不应，是之谓鸣象也。夫「豫」之时，九四以一阳为五阴之主，建侯行师，无所不利，况于其国邑也！间有倡而无和，其勿讨乎！故曰：㓙子曰：「初六鸣豫，志穷㓙也。」夫「豫」之初六，即「谦」之上六也。上六之应九三，初六之应九四，宜其不戒而孚矣。然在谦之时，则有谦让而不应之义；在「豫」之时，则有豫怠而不从之理。故上曰「鸣谦」，初曰「鸣豫」。方其在「谦」也，九三之震未出乎「坤」，故上六之志未得，而犹可以自托于谦，固乞致师之道矣。及其在「豫」也，九四之雷已奋乎地，故初六之志穷矣，而尚欲自安于「豫」，其可得乎？此其所以㓙也。</p><p>六二：介于石，不终日，贞吉。象曰：「不终日，贞吉」，以中正也。</p><p>六二，「艮」也。以阴居柔而在下卦之中，上无其应，而介乎初三之「坤」，达于四九之「震」，故曰「介于石」。艮为石，故有「介于石」之象。自「艮」而「震」，不涉他卦，故有「不终日」之象。夫静不专者，其动不直；守不固者，其发不勇。六二居中守正，体「艮」而在「坤」之中，可谓静之专而守之固矣。其在于「豫」，盖有「雷出地」之象焉。则二之「艮」也，岂其终止欤？所以察时而动也。其静也「介于石」，则其动也「不终日」，故曰「贞吉」。夫「震」也者，「乾」之「元」也；「艮」也者，「乾」之「贞」也。此二之所以为「贞吉」者也。子曰：「不终日，贞吉，以中正也。」又曰：知几其神乎？君子上交不謟，下交不渎，其知几乎？几者，动之微，吉之先见者也。君子见几而作，不俟终日，介如石焉。宁用终日，断可识矣。君子知微知彰，知柔知刚，万夫之望。「豫」之诸爻，惟六二中正，故孔子以为知几。上交不謟者，知六三之不足与有为也；下交不渎者，知初六之不足与有行也。以静观动，则动者不能逃；以正观邪，则邪者不能乱。方几之未至也，介然如石之坚；及其至也，起而乘之，不俟终日矣。若以謟渎而交，其能去之速乎？或曰：介于石，何也？曰：「艮」为石矣。以「艮」居「坤」，以六居二，乃不足以言其坚也。诗云：「我心匪石，不可转也。」与此同意。</p><p>六三：盱豫，悔，迟有悔。象曰：「盱豫」有「悔」，位不当也。</p><p>六三上体为「坎」，下体为「坤」，以阴为刚而在下卦之上，上无其应，而承于九四之震，故曰「盱豫，悔」。「盱」，视不正也，又曰上视也。进退不决者，其视睢盱。四为「震」，二为「艮」，以六居三，当进退之位，无「坤」「坎」之体而在「震」「艮」之间，见四之动而欲从之，故其视睢盱。然四以顺动，而三体阴柔，乐于趋下，是以豫怠而不能自奋也。既盱入「豫」，能无悔乎？迟得也。既悔于睢盱，遂追而得二。二「介于石」，而三又轻怀进退之志，是以不能无悔也。上交而謟，下交而渎，六三之谓矣。夫六二之静也，「介于石」，岂有悔豫之悔乎？其动也不终日，岂有迟待之悔乎？所以然者，二中正而三不当其位故也。子曰：「盱豫有悔，位不当也。」其小人之情状乎？</p><p>九四：由豫，大有得，勿疑，朋盍簪。象曰：「由豫，大有得」，志大行也。九四上体为「震」，下体亦为「震」，以「豫」居柔而在二卦之中，应乎初六之「坤」。「盱」三为「坎」，「盱」五亦为「坎」，「盱」二为「艮」，「盱」上亦为「艮」。故曰「由豫，由安行也」。顺动之义也，豫备也。记曰：「事豫则立，不豫则废。」「震」为动，「坤」为顺，「艮」为止，「坎」为陷。凡「豫」之时，患在于怠而陷，疑而止也；患在于顺而不动，动而不顺也。今四以阳刚而体乎震，动乎艮坎之中，下应乎坤，得夫顺动之义矣。顺以动，思患而豫防之，建侯行师，以正天下，五阴思欲无归，不可得也，故曰「大有得」。「大有得」者，上得其君，下得其民也。古者人臣居嫌疑之地，有上下之应，欲保其身而全其名，朋虽欲为天下国家立太平之基，建久安之业，同有疑惧而不敢为者矣。故曰「勿疑，朋盍簪」，大臣之义，以身当天下之应，国之存亡，民之死生，于是乎在，可以自疑而废之乎？国之有君，犹衣服之有冠是也。冠居于首，君之象也。簪下于冠，大臣之象也，所以贯发而正冠也。朋之言众也，盍之言合也。九四以一阳而在五阴之中，有簪发之象焉。所以然者，冠非簪无以总发，五非四无以得民也。古之人有行之者，伊尹、周公是已。使伊尹、周公惧嫌畏过，不敢有为，则太甲、成王将失民心，以至于亡，谁之咎也？是以管、蔡流言而周公不去，太甲悔过而伊尹乃归，大臣之义也。如召公之贤，犹不足以知此，故周公作书，勤勤恳恳，使之勿疑。圣贤之心，盖可以见。故子曰：「由豫，大有得，志大行也。」其伊尹、周公之谓乎？旧说五阴由我以致「豫」，故曰「由豫」。九四大臣之义，镇抚国家，亲附百姓，兴利除害，皆所当为。必曰「由我以致豫」，不亦失其义乎？又维以「大有得」，勿疑之辞，将非人臣之志矣。故曰：「豫之训，当以顺动为义。」</p><p>六五：贞疾，恒不死。象曰：「六五贞疾」，乘刚也。「恒不死」，中未亡也。</p><p>六五，「坎」也。以阴居刚，而在上卦之中，下无其应，而乘于九四之「震」，故曰「贞疾」。「坎」为病，故有疾象。六五，君也。九四，臣也。上下五阴皆归于四，五以柔弱之资，履于其上，此弱主驭强臣之象也。以此为「贞」，斯其疾矣。然方「豫」之时，刚上而柔下，上动而下顺，虽有刚强之臣，必无逆乱之事，故曰：「恒不死」。「恒」，久也。刚上而柔下，恒之象也。自古乱臣贼子之兴，未尝不变乱纲纪，反易衣裳，使人情猜于无君，然后有以逞其私而灭其君，故曰：非一朝一夕之故，其所由来者渐矣。今「豫」之六五，虽以柔乘刚，然君臣之分未变也，故虽「贞疾」，久而不死。譬如草木蠹蚀其干，而未啮其心，犹可救耳。方「豫」之时，君无大恶，民心未去也，虽有逆乱之臣，不得而取之矣。故曰：「六五贞疾」，乘刚也；「恒不死」，中未亡也。或曰：然则「逸豫」之王，不能以失人心乎？曰：所谓疾者，犹可救云尔。若疾久不治，蠹久不除，未有不死者也。上六「冥豫」，其可长乎？或曰：九四不失大臣之义，则五之乘刚，何以为疾？曰：非四为之疾也，以四之乘权而知宴疾也。疾也者，宴安鸩毒之谓也。使五非太甲、成王之君，则四非伊尹、周公之臣，以伊尹、周公当九四之称，是以太甲、成王将有逸豫之失也。疾而未死，不其然欤！说者或以汉、魏末世之君当此爻之义，彼之忘形己见，岂所谓不死者哉！</p><p>上六，冥豫，成有渝，无咎。象曰：「冥豫」在上，何可长也！</p><p>上六，「艮」也。以阴居柔，而在上卦之上，下无其应，而近于九四之震，故曰冥豫，冥晦也。四为「震」，五为「坎」，上为「艮」，「震」为旦，「坎」为夜。「艮」者，夜之将旦也。下卦为日，上卦为夜，上卦之终，夜之将旦者也，故曰「成有渝」。「艮」反则为「震」，「震」反则为「艮」，静而能静者，其动不旋踵矣，故曰「无咎」。夫夜者，人之所休息也，于是焉而豫怠，未失其节也。至于上六，豫既成矣，成而有渝，则向晦而息，昧爽而兴，又何咎之有！成而不渝，是谓俾昼作夜，欲无㓙得乎！故子曰：「冥豫在上，何可长也！太甲思庸，无俾世迷。」其谓之是乎！或问：「下为日，上卦为夜，何所据乎？」曰：易之取象，皆于是矣。六二言「不终日」，乾之九三言「终日」是也。夫六二之「艮」，与上六之「艮」，其近于震一也。二为介石，上为冥豫者，二中正而上处一卦之终故也。知象之无常，然后可与言易矣。周易经传集解卷八，</p>',39)])])}const m=a(s,[["render",n]]);export{h as __pageData,m as default};
